(function() {
  function init(el) {
    var startOn = ["load"], stopOn = [], pauseOn = [], resumeOn = ["load"];
    var state = "stopped", finished = false, pendingOff = false, reversed = false;
    function forward() {}
    function rest() { forward(); el.classList.remove("px-anim-enabled", "px-anim-playing"); el.getBoundingClientRect(); state = "stopped"; finished = false; }
    function on() { pendingOff = false; forward(); if (finished) { el.classList.remove("px-anim-enabled", "px-anim-playing"); el.getBoundingClientRect(); } el.classList.add("px-anim-enabled", "px-anim-playing"); finished = false; state = "playing"; }
    function pause() { pendingOff = false; el.classList.remove("px-anim-playing"); state = "paused"; }
    function resume() { el.classList.add("px-anim-enabled", "px-anim-playing"); state = "playing"; }
    function performOff() { pendingOff = false; rest(); }
    function off() { performOff(); }
    el.addEventListener("animationend", function() {
      if (reversed) { rest(); return; }
      finished = true;
      if (pendingOff) { performOff(); return; }
      state = "stopped";
    });
    function fire(ev, direct) {
      if (state === "stopped") { if (startOn.indexOf(ev) >= 0) requestStart(direct); }
      else if (state === "paused") { if (resumeOn.indexOf(ev) >= 0) requestStart(direct); else if (stopOn.indexOf(ev) >= 0) off(); }
      else { if (pauseOn.indexOf(ev) >= 0) pause(); else if (stopOn.indexOf(ev) >= 0) off(); }
    }
    function start() { if (state === "paused") resume(); else on(); }
    var threshold = 0.5, debounce = 150;
    var steps = []; for (var s = 0; s <= 20; s++) steps.push(s / 20);
    function pxRatio(i) {
      var t = i.boundingClientRect, v = i.intersectionRect;
      if (!t || !t.height || !v) return i.intersectionRatio;
      var vp = Math.min(window.innerHeight || Infinity, i.rootBounds ? i.rootBounds.height : Infinity);
      if (!isFinite(vp)) vp = t.height;
      var d = Math.min(t.height, vp);
      return d > 0 ? v.height / d : i.intersectionRatio;
    }
    var open = false, timer = 0, startPending = false, heldByGate = false;
    function pxOpen() {
      timer = 0; if (open) return; open = true;
      if (startPending) { startPending = false; heldByGate = false; start(); }
      else if (heldByGate) { heldByGate = false; if (state === "playing") el.classList.add("px-anim-enabled", "px-anim-playing"); }
    }
    function pxClose() {
      if (timer) { clearTimeout(timer); timer = 0; }
      if (!open) return; open = false;
      if (state !== "playing") return;
      el.classList.remove("px-anim-playing"); heldByGate = true;
    }
    function requestStart(direct) {
      if (direct || open) { if (timer) { clearTimeout(timer); timer = 0; } open = true; startPending = false; heldByGate = false; start(); return; }
      startPending = true;
    }
    if (typeof IntersectionObserver === "undefined") { open = true; } else {
      new IntersectionObserver(function(e) { e.forEach(function(i) {
        var r = i.isIntersecting ? pxRatio(i) : 0;
        if (document.visibilityState === "hidden") { pxClose(); return; }
        if (r > 0 && r >= threshold) { if (!open && !timer) { timer = debounce > 0 ? setTimeout(pxOpen, debounce) : (pxOpen(), 0); } }
        else if (r <= 0) { pxClose(); }
        else if (!open && timer) { clearTimeout(timer); timer = 0; }
      }); }, { threshold: steps }).observe(el);
    }
    fire("load", false);
  }
  var el = document.currentScript.closest('svg');
  (el ? [el] : document.querySelectorAll("#_px_3gda5ip3")).forEach(init);
})();
